frappe.ui.form.on('Expense Claim', {
    cost_center: function(frm) {
        // Khi thay đổi cost_center của Expense Claim
        apply_cost_center_to_expenses(frm);
    },
    expenses_add: function(frm, cdt, cdn) {
        // Khi thêm mới một dòng trong bảng con 'expenses'
        apply_cost_center_to_expenses(frm);
    },
    before_save: function(frm) {
        // Cập nhật cost_center cho toàn bộ bảng con mỗi khi lưu tài liệu
        apply_cost_center_to_expenses(frm);
    }
});

// Hàm để áp dụng cost_center của Expense Claim lên toàn bộ bảng con
function apply_cost_center_to_expenses(frm) {
    if (frm.doc.cost_center) {
        // Nếu cost_center của Expense Claim có giá trị
        frm.doc.expenses.forEach(function(expense) {
            expense.cost_center = frm.doc.cost_center;
        });
        frm.refresh_field('expenses'); // Cập nhật lại giao diện bảng con
    }
    // Nếu không có cost_center ở Expense Claim thì giữ nguyên các giá trị cost_center hiện có của bảng con
}

frappe.ui.form.on('Petty Expense', {  // Thay 'Your DocType' bằng DocType bạn muốn áp dụng filter
    refresh: function(frm) {
        // Lấy đối tượng trường 'expense_account' từ form
        frm.fields_dict['expense_account'].get_query = function(doc, cdt, cdn) {
            return {
                filters: {
                    // Thêm điều kiện lọc, ví dụ lọc các tài khoản chi tiêu đang hoạt động
                    'is_group': 0,  // Lọc để chỉ lấy các tài khoản không phải nhóm (ví dụ: là tài khoản chi tiêu)
                    'root_type': 'Expense'  // Lọc chỉ lấy tài khoản loại 'Expense'
                }
            };
        };
    },

    mode_of_payment: function(frm) {
        if (frm.doc.mode_of_payment) {
            // Truy vấn dữ liệu từ bảng con của mode_of_payment để lấy default_account
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Mode of Payment',
                    name: frm.doc.mode_of_payment
                },
                callback: function(r) {
                    if (r.message) {
                        var accounts = r.message.accounts || [];
                        var defaultAccount = null;

                        // Tìm default_account trong bảng con
                        accounts.forEach(function(account) {
                            if (account.default_account) {
                                defaultAccount = account.default_account;
                            }
                        });

                        // Cập nhật trường payment_account với giá trị default_account tìm được
                        if (defaultAccount) {
                            frm.set_value('payment_account', defaultAccount);
                        }
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Project', {
    refresh: function(frm) {
        // Gọi hàm tính tổng petty expense khi form dự án được tải
        update_total_petty_expense(frm);
