});

// Hàm tính tổng petty expense
function update_total_petty_expense(frm) {
    // Kiểm tra nếu có giá trị cho tên dự án trong trường custom_project
    if (frm.doc.name) {
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Petty Expense',
                fields: ['amount'],
                filters: {
                    'custom_project': frm.doc.name  // Lọc theo tên dự án
                }
            },
            callback: function(r) {
                if (r.message) {
                    // Tính tổng số tiền từ các bản ghi đã lọc
                    let total_amount = r.message.reduce((sum, petty_expense) => sum + petty_expense.amount, 0);

                    // Cập nhật giá trị tổng vào trường custom_total_petty_expense
                    frm.set_value('custom_total_petty_expense', total_amount);
                    frm.refresh_field('custom_total_petty_expense');
                }
            }
        });
    }
}

frappe.listview_settings["Attendance"] = {
	add_fields: ["status", "attendance_date"],

	get_indicator: function (doc) {
		if (["Present", "Work From Home"].includes(doc.status)) {
			return [__(doc.status), "green", "status,=," + doc.status];
		} else if (["Absent", "On Leave"].includes(doc.status)) {
			return [__(doc.status), "red", "status,=," + doc.status];
		} else if (doc.status == "Half Day") {
			return [__(doc.status), "orange", "status,=," + doc.status];
		}
	},

	onload: function (list_view) {
		let me = this;

		list_view.page.add_inner_button(__("Mark Attendance"), function () {
			let first_day_of_month = moment().startOf("month");

			if (moment().toDate().getDate() === 1) {
				first_day_of_month = first_day_of_month.subtract(1, "month");
			}

			let dialog = new frappe.ui.Dialog({
				title: __("Mark Attendance"),
				fields: [
					{
						fieldname: "employee",
						label: __("For Employee"),
						fieldtype: "Link",
						options: "Employee",
						get_query: () => {
							return {
								query: "erpnext.controllers.queries.employee_query",
							};
						},
						reqd: 1,
						onchange: () => me.reset_dialog(dialog),
					},
					{
						fieldtype: "Section Break",
						fieldname: "time_period_section",
						hidden: 1,
					},
					{
						label: __("Start"),
						fieldtype: "Date",
						fieldname: "from_date",
						reqd: 1,
						default: first_day_of_month.toDate(),
						onchange: () => me.get_unmarked_days(dialog),
					},
					{
						fieldtype: "Column Break",
						fieldname: "time_period_column",
					},
					{
						label: __("End"),
						fieldtype: "Date",
						fieldname: "to_date",
						reqd: 1,
						default: moment().subtract(1, "days").toDate(),
						onchange: () => me.get_unmarked_days(dialog),
					},
					{
						fieldtype: "Section Break",
						fieldname: "days_section",
						hidden: 1,
					},
					{
                        fieldname: "custom_project",
                        label: __("Project"),
                        fieldtype: "Link",
                        options: "Project",  // Liên kết với Doctype "Project"
                        reqd: 0,  // Không bắt buộc
                    },
					{
						label: __("Status"),
						fieldtype: "Select",
						fieldname: "status",
						options: ["Present", "Absent", "Half Day", "Work From Home"],
						reqd: 1,
					},
					{
						label: __("Exclude Holidays"),
						fieldtype: "Check",
						fieldname: "exclude_holidays",
						onchange: () => me.get_unmarked_days(dialog),
					},
					{
						label: __("Unmarked Attendance for days"),
						fieldname: "unmarked_days",
						fieldtype: "MultiCheck",
						options: [],
						columns: 2,
						select_all: true,
					},
				],
				primary_action(data) {
					if (cur_dialog.no_unmarked_days_left) {
						frappe.msgprint(
							__(
								"Attendance from {0} to {1} has already been marked for the Employee {2}",
								[data.from_date, data.to_date, data.employee],
							),
						);
					} else {
						frappe.confirm(
							__("Mark attendance as {0} for {1} on selected dates?", [
								data.status,
								data.employee,
							]),
							() => {
								frappe.call({
									method: "hrms.hr.doctype.attendance.attendance.mark_bulk_attendance",
									args: {
										data: data,
									},
									callback: function (r) {
										if (r.message === 1) {
											frappe.show_alert({
												message: __("Attendance Marked"),
												indicator: "blue",
											});
											cur_dialog.hide();
										}
									},
								});
							},
						);
					}
					dialog.hide();
					list_view.refresh();
				},
				primary_action_label: __("Mark Attendance"),
			});
			dialog.show();
		});
	},

	reset_dialog: function (dialog) {
		let fields = dialog.fields_dict;

		dialog.set_df_property("time_period_section", "hidden", fields.employee.value ? 0 : 1);

		dialog.set_df_property("days_section", "hidden", 1);
		dialog.set_df_property("unmarked_days", "options", []);
		dialog.no_unmarked_days_left = false;
		fields.exclude_holidays.value = false;

		fields.to_date.datepicker.update({
			maxDate: moment().subtract(1, "days").toDate(),
		});

		this.get_unmarked_days(dialog);
	},

	get_unmarked_days: function (dialog) {
		let fields = dialog.fields_dict;
		if (fields.employee.value && fields.from_date.value && fields.to_date.value) {
			dialog.set_df_property("days_section", "hidden", 0);
			dialog.set_df_property("status", "hidden", 0);
			dialog.set_df_property("exclude_holidays", "hidden", 0);
			dialog.no_unmarked_days_left = false;

			frappe
				.call({
					method: "hrms.hr.doctype.attendance.attendance.get_unmarked_days",
					async: false,
					args: {
						employee: fields.employee.value,
						from_date: fields.from_date.value,
						to_date: fields.to_date.value,
						exclude_holidays: fields.exclude_holidays.value,
					},
				})
				.then((r) => {
					var options = [];

					for (var d in r.message) {
						var momentObj = moment(r.message[d], "YYYY-MM-DD");
						var date = momentObj.format("DD-MM-YYYY");
						options.push({
							label: date,
							value: r.message[d],
							checked: 1,
						});
					}

					dialog.set_df_property(
						"unmarked_days",
						"options",
						options.length > 0 ? options : [],
					);
					dialog.no_unmarked_days_left = options.length === 0;
				});
		}
	},
};

frappe.ui.form.on('BOM', {
    refresh: function(frm) {
        calculate_cost_per_unit(frm);
    },
    total_cost: function(frm) {
        calculate_cost_per_unit(frm);
    },
    quantity: function(frm) {
        calculate_cost_per_unit(frm);
    }
});

function calculate_cost_per_unit(frm) {
    const total_cost = frm.doc.total_cost || 0;
    const quantity = frm.doc.quantity || 0;

    if (quantity !== 0) {
        frm.set_value('custom_cost_per_unit', total_cost / quantity);
    } else {
        frm.set_value('custom_cost_per_unit', 0);
    }
}

frappe.ui.form.on('Hoa Don Ra Vao', {
    total: function(frm) {
        calculate_vat_and_total(frm);
        calculate_fee_amount(frm);
    },
    tax_rate: function(frm) {
        calculate_vat_and_total(frm);
    },
    payment: function(frm) {
        check_payment_complete(frm);
    },
    fee: function(frm) {
        calculate_fee_amount(frm);
    },
    before_submit: function(frm) {
        const party = frm.doc.party;
        if (party === "Supplier") {
            frm.set_value('title', frm.doc.supplier_name || '');
        } else if (party === "Customer") {
            frm.set_value('title', frm.doc.customer_name || '');
        }
    }
});

function calculate_vat_and_total(frm) {
    const total = frm.doc.total || 0;
    const tax_rate = frm.doc.tax_rate || 0;

    const vat = (total * tax_rate) / 100;
    const grand_total = total + vat;

    frm.set_value('vat', vat);
    frm.set_value('grand_total', grand_total).then(() => {
        check_payment_complete(frm);
    });
}

function check_payment_complete(frm) {
    const payment = frm.doc.payment || 0;
    const grand_total = frm.doc.grand_total || 0;

    let status = 'Chưa xử lý';

    if (payment === 0) {
        status = 'Chưa xử lý';
    } else if (payment < grand_total) {
        status = 'Xử lý dở dang';
    } else if (payment >= grand_total) {
        status = 'Đã xử lý';
    }

    frm.set_value('is_complete', status);
}

function calculate_fee_amount(frm) {
    const total = frm.doc.total || 0;
    const fee = frm.doc.fee || 0;

    const fee_amount = (fee * total) / 100;

    frm.set_value('fee_amount', fee_amount);
}

frappe.ui.form.on('Hoa Don Ra Vao', {
    refresh(frm) {
        if (frm.doc.docstatus === 0) {
            frm.add_custom_button(__('Get Total From'), function () {
                show_invoice_source_dialog(frm);
            });
        }
    }
});

function show_invoice_source_dialog(frm) {
    frappe.prompt([
        {
            label: __('Select Source'),
            fieldname: 'source',
            fieldtype: 'Select',
            options: ['Sales Invoice', 'Purchase Invoice'],
            reqd: 1,
            default: 'Sales Invoice'
        }
    ], function(values) {
        const source = values.source;

        if (source === 'Sales Invoice' && !frm.doc.customer) {
            frappe.msgprint({
                title: __('Validation Error'),
                message: __('Please Select a Customer'),
                indicator: 'red'
            });
            return;
        }

        if (source === 'Purchase Invoice' && !frm.doc.supplier) {
            frappe.msgprint({
                title: __('Validation Error'),
                message: __('Please Select a Supplier'),
                indicator: 'red'
            });
            return;
        }

        show_invoice_list(frm, source);
    }, __('Get From'), __('Continue'));
}

function show_invoice_list(frm, source) {
    let filters = { docstatus: 1 };

    if (source === 'Sales Invoice') {
        filters.customer = frm.doc.customer;
    } else {
        filters.supplier = frm.doc.supplier;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: source,
            filters: filters,
            fields: ['name', 'posting_date', 'total', 'net_total', 'outstanding_amount'],
            limit_page_length: 100,
            order_by: 'posting_date desc'
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                show_invoice_selection_dialog(frm, r.message, source);
            } else {
                frappe.msgprint({
                    title: __('No Data'),
                    message: __('No {0} found with current filters', [source]),
                    indicator: 'yellow'
                });
            }
        }
    });
}

function show_invoice_selection_dialog(frm, invoices, source) {
    let dialog;

    function render_table(filtered_invoices) {
        let table_html = `
            <style>
                .invoice-table { width: 100%; min-width: 700px; }
                .invoice-table th, .invoice-table td {
                    padding: 8px;
                    text-align: left;
                    border-bottom: 1px solid #ddd;
                    white-space: nowrap;
                }
                .invoice-table th {
                    background-color: #f5f5f5;
                    font-weight: bold;
                }
                .invoice-radio { margin-right: 5px; }
            </style>
            <table class="invoice-table">
                <thead>
                    <tr>
                        <th>Select</th>
                        <th>Invoice No</th>
                        <th>Date</th>
                        <th>Total</th>
                        <th>Net Total</th>
                        <th>Outstanding</th>
                    </tr>
                </thead>
                <tbody>
        `;

        filtered_invoices.forEach(inv => {
            table_html += `
                <tr>
                    <td>
                        <input type="radio" name="invoice_selection" class="invoice-radio"
                            value="${inv.name}" data-net-total="${inv.net_total || 0}">
                    </td>
                    <td>${inv.name}</td>
                    <td>${frappe.datetime.str_to_user(inv.posting_date || '')}</td>
                    <td>${frappe.format(inv.total || 0, { fieldtype: 'Currency' })}</td>
                    <td>${frappe.format(inv.net_total || 0, { fieldtype: 'Currency' })}</td>
                    <td>${frappe.format(inv.outstanding_amount || 0, { fieldtype: 'Currency' })}</td>
                </tr>
            `;
        });

        table_html += `
                </tbody>
            </table>
        `;

        dialog.fields_dict.invoice_html.$wrapper.html(table_html);
    }

    dialog = new frappe.ui.Dialog({
        title: __('Select {0}', [source]),
        size: 'large',
        fields: [
            {
                label: __('From Date'),
                fieldname: 'from_date',
                fieldtype: 'Date',
                default: frappe.datetime.add_months(frappe.datetime.get_today(), -1),
                onchange: apply_date_filter
            },
            {
                label: __('To Date'),
                fieldname: 'to_date',
                fieldtype: 'Date',
                default: frappe.datetime.get_today(),
                onchange: apply_date_filter
            },
            {
                fieldtype: 'HTML',
                fieldname: 'invoice_html'
            }
        ],
        primary_action_label: __('Select Invoice'),
        primary_action: function () {
            const selected = dialog.$wrapper.find('input[name="invoice_selection"]:checked');
            if (selected.length === 0) {
                frappe.msgprint(__('Please select an invoice'));
                return;
            }

            const net_total = parseFloat(selected.attr('data-net-total')) || 0;
            frm.set_value('total', net_total);
            dialog.hide();
        },
        secondary_action_label: __('Cancel'),
        secondary_action: () => dialog.hide()
    });

    dialog.show();
    render_table(invoices);  // Initial render

    function apply_date_filter() {
        const from = dialog.get_value('from_date');
        const to = dialog.get_value('to_date');

        let filtered = invoices;

        if (from || to) {
            filtered = invoices.filter(inv => {
                const date = frappe.datetime.str_to_obj(inv.posting_date);
                if (from && date < frappe.datetime.str_to_obj(from)) return false;
                if (to && date > frappe.datetime.str_to_obj(to)) return false;
                return true;
            });
        }

        render_table(filtered);
    }
}
